const sortMessage = `-- name: SortMessage :exec
WITH changed AS (
  UPDATE message SET category = coalesce($3::text, category), spam = coalesce($4::boolean, spam)
  WHERE id = $2 AND account_id = $1
    AND (category <> coalesce($3::text, category) OR spam <> coalesce($4::boolean, spam))
  RETURNING id
), v AS (
  UPDATE mail_account SET version = version + 1 WHERE id = $1 AND EXISTS (SELECT FROM changed) RETURNING version
)
INSERT INTO change_log (account_id, version, entity, entity_id, op)
SELECT $1, v.version, 'message', $2, 'upsert' FROM v
`

type SortMessageParams struct {
	AccountID string
	ID        string
	Category  pgtype.Text
	Spam      pgtype.Bool
}

// Puts a message into a tab or marks it spam or not, and logs the change, unless nothing changes.
func (q *Queries) SortMessage(ctx context.Context, arg SortMessageParams) error {
	_, err := q.db.Exec(ctx, sortMessage,
		arg.AccountID,
		arg.ID,
		arg.Category,
		arg.Spam,
	)
	return err
}

const startSend = `-- name: StartSend :one
INSERT INTO outbox (draft_id, account_id, state, payload) VALUES ($1, $2, 'sending', $3)
ON CONFLICT (draft_id) DO UPDATE SET state = 'sending', payload = EXCLUDED.payload, error = NULL, updated_at = now()
WHERE outbox.state <> 'sent' AND outbox.account_id = EXCLUDED.account_id
RETURNING state
`

type StartSendParams struct {
	DraftID   string
	AccountID string
	Payload   []byte
}

// Claims a draft's send. No row: it went out already.
func (q *Queries) StartSend(ctx context.Context, arg StartSendParams) (string, error) {
	row := q.db.QueryRow(ctx, startSend, arg.DraftID, arg.AccountID, arg.Payload)
	var state string
	err := row.Scan(&state)
	return state, err
}

const takeDueJobs = `-- name: TakeDueJobs :many
DELETE FROM scheduled
WHERE id IN (SELECT id FROM scheduled WHERE run_at <= now() ORDER BY run_at LIMIT 20 FOR UPDATE SKIP LOCKED)
RETURNING id, account_id, run_at, kind, payload
`

// Taken jobs are gone; a job that fails is added again.
func (q *Queries) TakeDueJobs(ctx context.Context) ([]Scheduled, error) {
	rows, err := q.db.Query(ctx, takeDueJobs)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []Scheduled
	for rows.Next() {
		var i Scheduled
		if err := rows.Scan(
			&i.ID,
			&i.AccountID,
			&i.RunAt,
			&i.Kind,
			&i.Payload,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const takeDueSends = `-- name: TakeDueSends :many
UPDATE outbox SET state = 'sending', updated_at = now()
WHERE draft_id IN (
	SELECT draft_id FROM outbox
	WHERE (state = 'scheduled' AND run_at <= now()) OR (state = 'sending' AND run_at IS NOT NULL AND updated_at < now() - interval '30 minutes')
	ORDER BY run_at LIMIT 20 FOR UPDATE SKIP LOCKED
)
RETURNING draft_id, account_id, payload
`

type TakeDueSendsRow struct {
	DraftID   string
	AccountID string
	Payload   []byte
}

// Due ones, and ones taken before that never got anywhere, e.g. the engine stopped in between: sending one twice is
// harmless, StartSend lets it out once.
func (q *Queries) TakeDueSends(ctx context.Context) ([]TakeDueSendsRow, error) {
	rows, err := q.db.Query(ctx, takeDueSends)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []TakeDueSendsRow
	for rows.Next() {
		var i TakeDueSendsRow
		if err := rows.Scan(&i.DraftID, &i.AccountID, &i.Payload); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const threadsFor = `-- name: ThreadsFor :many
SELECT DISTINCT thread_id FROM message
WHERE account_id = $1 AND thread_id <> ''
  AND (message_id = ANY($2::text[])
    OR ($3::text <> '' AND (refs && ARRAY[$3::text] OR message_id = $3::text)))
`

type ThreadsForParams struct {
	AccountID string
	Refs      []string
	MessageID string
}

// Conversations a message belongs to: those of the messages it answers, of messages that answer it, and of other
// copies of it (the same mail in Sent and INBOX). Without a Message-ID only the first counts.
func (q *Queries) ThreadsFor(ctx context.Context, arg ThreadsForParams) ([]string, error) {
	rows, err := q.db.Query(ctx, threadsFor, arg.AccountID, arg.Refs, arg.MessageID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []string
	for rows.Next() {
		var thread_id string
		if err := rows.Scan(&thread_id); err != nil {
			return nil, err
		}
		items = append(items, thread_id)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

